export type TextFragmentOffset = { index: number; start: number; end: number };
export function textFragmentsForOffsets(
  lengths: readonly number[],
  start: number,
  end: number,
): TextFragmentOffset[] {
  if (
    !Number.isInteger(start) ||
    !Number.isInteger(end) ||
    start < 0 ||
    end <= start ||
    lengths.some((length) => !Number.isInteger(length) || length < 0)
  )
    return [];
  const total = lengths.reduce((sum, length) => sum + length, 0);
  if (end > total) return [];
  const fragments: TextFragmentOffset[] = [];
  let offset = 0;
  lengths.forEach((length, index) => {
    const next = offset + length;
    const localStart = Math.max(0, start - offset);
    const localEnd = Math.min(length, end - offset);
    if (localEnd > localStart)
      fragments.push({ index, start: localStart, end: localEnd });
    offset = next;
  });
  return fragments;
}

